// SPDX-License-Identifier: MIT
import assert from 'node:assert/strict';
import test from 'node:test';
import { fetchStatus } from '../src/status-service.mjs';

test('fetchStatus retries reader failures up to success and calls it without arguments', async () => {
  const seenArgs = [];
  const status = { state: 'ready' };
  let calls = 0;

  const result = await fetchStatus(async (...args) => {
    calls += 1;
    seenArgs.push(args);
    if (calls < 3) throw new Error('temporary failure');
    return status;
  });

  assert.equal(result, status);
  assert.equal(calls, 3);
  assert.deepEqual(seenArgs, [[], [], []]);
});
